// 在排序数组中查找元素的第一个和最后一个位置
public class FindFirstAndLastPosition {

    public int[] searchRange(int[] nums, int target) {
        int leftIndex = findLeftBound(nums, target);
        int rightIndex = findRightBound(nums, target);
        return new int[]{leftIndex, rightIndex};
    }

    // 查找左边界（第一个出现的位置）
    private int findLeftBound(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        int result = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] >= target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
            if (nums[mid] == target) {
                result = mid;
            }
        }

        return result;
    }

    // 查找右边界（最后一个出现的位置）
    private int findRightBound(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        int result = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
            if (nums[mid] == target) {
                result = mid;
            }
        }

        return result;
    }

    // 测试
    public static void main(String[] args) {
        FindFirstAndLastPosition solution = new FindFirstAndLastPosition();
        int[] nums = {5, 7, 7, 8, 8, 10};
        System.out.println(Arrays.toString(solution.searchRange(nums, 8))); // [3, 4]
        System.out.println(Arrays.toString(solution.searchRange(nums, 6))); // [-1, -1]
    }
}
